document.addEventListener("DOMContentLoaded",()=>{window.location.hostname;const e=`${"undefined"!=typeof CONFIG&&CONFIG.API_BASE?CONFIG.API_BASE:"http://192.168.3.85:9090"}/camData/`,t=document.querySelector(".content-wrapper");if(!t)return;t.innerHTML='\n        <div class="video-content-layout">\n            \x3c!-- 左側影像預覽與控制 --\x3e\n            <div class="video-left-pane">\n                <div class="video-controls-group">\n                    \x3c!-- ⚡ 這裡改成單一一顆按鈕 --\x3e\n                    <button class="vid-action-btn btn-show" id="btn-toggle-video">畫面顯示</button>\n                </div>\n                <div class="video-display-box" id="videoBox">\n                    <span class="video-placeholder-text" id="placeholderText">影像串流已關閉</span>\n                    <img id="camStreamImg" alt="Camera" />\n                </div>\n            </div>\n\n            \x3c!-- 右側闖入紀錄面板 --\x3e\n            <div class="video-right-pane" id="logContainer">\n                \x3c!-- 動態生成的日誌會塞在這裡 --\x3e\n            </div>\n        </div>\n    ';const n=document.getElementById("btn-toggle-video"),d=document.getElementById("camStreamImg"),i=document.getElementById("placeholderText"),o=document.getElementById("logContainer");let a=!1;async function s(){try{const t=await fetch(e);if(!t.ok)return;const n=await t.json(),d=Array.isArray(n)?n:[n];o.innerHTML="",d.forEach(e=>{const t=e.deviceId||"CAM",n=e.danger?"是":"否",d=e.personCount||0,i=e.timestamp?new Date(1e3*e.timestamp):new Date,a=`\n                    <div class="log-entry">\n                        <div>裝置名稱：${t}</div>\n                        <div>是否有人闖入：${n}</div>\n                        <div>闖入人數：${d}</div>\n                        <div>闖入時間點：${`${i.getMonth()+1}/${i.getDate()} ${String(i.getHours()).padStart(2,"0")}:${String(i.getMinutes()).padStart(2,"0")}`}</div>\n                    </div>\n                `;o.insertAdjacentHTML("beforeend",a)}),0===d.length&&(o.innerHTML='<div style="color: #666; text-align: center; padding: 20px; font-size: 24px;">目前尚無闖入紀錄</div>')}catch(e){console.warn("無法取得攝影機 API 紀錄",e)}}n.addEventListener("click",()=>{a=!a,a?(d.src="http://192.168.3.85:5000/video_feed",d.style.display="block",i.style.display="none",n.textContent="畫面關閉",n.classList.remove("btn-show"),n.classList.add("btn-hide")):(d.src="",d.style.display="none",i.style.display="block",n.textContent="畫面顯示",n.classList.remove("btn-hide"),n.classList.add("btn-show"))}),s(),setInterval(s,3e3)});